import{H as e,V as t,et as n,j as r}from"./chunks/framework.BK8iTJR-.js";var i=JSON.parse(`{"title":"Esercizi","description":"","frontmatter":{},"headers":[],"relativePath":"esercizi/index.md","filePath":"esercizi/index.md"}`),a={name:`esercizi/index.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="esercizi" tabindex="-1">Esercizi <a class="header-anchor" href="#esercizi" aria-label="Permalink to “Esercizi”">​</a></h1><p>Questa parte del sito vuole insegnarti come risolvere gli esercizi di matematica: non e&#39; un eserciziario anche se puoi usarlo come tale Per gli esercizi di matematica non e&#39; sufficiente conoscere la teoria, bisogna anche seguire un metodo logico di soluzione che sara&#39; diverso a seconda del tipo di esercizio che vuoi risolvere: Ad esempio un esercizio di algebra andra&#39; affrontato in modo diverso da un esercizio di geometria anche dal punto di vista logico Vedremo insieme come sviluppare i vari possibili metodi di soluzione cercando di porre l&#39;accento sul perche&#39; fare piuttosto che sul come fare</p><h2 id="istruzioni-per-l-uso" tabindex="-1">Istruzioni per l&#39;uso <a class="header-anchor" href="#istruzioni-per-l-uso" aria-label="Permalink to “Istruzioni per l&#39;uso”">​</a></h2><p><strong>Perché fare esercizi</strong></p><p>La matematica ti fornisce degli &quot;strumenti&quot;; cos&#39;è uno strumento? È qualcosa che usi per operare delle trasformazioni su qualcos&#39;altro: ad esempio con una chiave inglese sviti un bullone, con le scomposizioni trasformi delle somme in prodotti; con le equazioni individui un valore che ti risolve un problema,...</p><p>La chiave inglese, le scomposizioni, le equazioni,... sono degli strumenti e, per usare tali strumenti al meglio serve l&#39;esercizio: più esercizi fai, meglio padroneggi gli strumenti e sai applicarli alle varie situazioni</p><p>Fare esercizi serve ad acquisire esperienza e manualità.</p><p>Una cosa importante da tener presente nel fare gli esercizi è che <strong>è fondamentale capire l&#39;errore fatto</strong>, solo in questo modo potrai correggerti per il futuro, quindi quando un esercizio &quot;non viene&quot; è controproducente rifarlo da capo: devi invece ripassare tutti i passaggi fatti, partendo dall&#39;inizio finché non trovi l&#39;errore; vedrai che non è tempo perso</p><p>Inoltre tieni presente che è più importante il capire <strong>perché</strong> fare un passaggio piuttosto che il <strong>come</strong> farlo: se capisci il perché dei vari passaggi poi diventa facile capire come fare l&#39;esercizio; io cercherò di mostrarti preferibilmente il perché dei vari passaggi per ogni esercizio</p><hr><p>Questi esercizi sono pensati per quelli che hanno qualche difficoltà nelle applicazioni, cioè riescono in teoria ma sono una frana nei compiti in classe:</p><p>qui troverai esercizi semplici, quelli che servono per iniziare, poi, una volta capace di eseguire i primi passi dovrai procedere in modo autonomo</p><p>Gli esercizi, almeno quelli iniziali, vengono svolti in tre modi diversi</p><ul><li><p><strong>Soluzione</strong> Ti viene fornito lo svolgimento dell&#39;esercizio</p></li><li><p><strong>Sviluppo</strong> Puoi seguire lo svolgimento dell&#39;esercizio passaggio per passaggio con la motivazione di tutti i passaggi, anche i più semplici</p></li><li><p><strong>Apprendimento</strong><strong>(da scegliere se proprio non hai idea di come fare)</strong> Prendi carta e penna e, insieme, passaggio per passaggio svilupperemo l&#39;esercizio, io sul computer e tu sul foglio.</p></li></ul><hr><p>Tu scegli lo svolgimento dell&#39;esercizio che ritieni più adatto alla tua preparazione</p><p>Ora chiudi questa pagina e passa agli esercizi</p><p><strong class="text-red">Buon lavoro!</strong></p>`,18)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};